function initOsceMenu() {
  const files = Array.isArray(globalThis.agoraSourceFiles) ? globalThis.agoraSourceFiles : [];
  const groups = new Map();
  const label = value => value.replace(/\.md$/i, '').replace(/[-_]/g, ' ');
  for (const file of files) {
    const parts = file.split('/');
    const specialty = parts.length > 1 ? parts.slice(0, -1).join(' / ') : 'References';
    if (!groups.has(specialty)) groups.set(specialty, []);
    groups.get(specialty).push({file, title: label(parts[parts.length - 1])});
  }
  const el = id => document.getElementById(id);
  let selected = null;
  let current = [...groups.values()].flat();
  function choose(topic) {
    selected = topic;
    el('selection').textContent = topic.title;
    el('start').disabled = false;
    for (const button of el('topics').children) button.setAttribute('aria-pressed', String(button.dataset.source === topic.file));
  }
  function show(specialty) {
    current = groups.get(specialty);
    el('categories').hidden = true; el('condition-page').hidden = false;
    el('specialty-title').textContent = label(specialty); el('topics').replaceChildren();
    for (const topic of current) {
      const button = document.createElement('button'); button.className = 'condition';
      button.textContent = topic.title; button.dataset.source = topic.file;
      button.setAttribute('aria-pressed', String(selected?.file === topic.file));
      button.onclick = () => choose(topic); el('topics').append(button);
    }
  }
  const grid = document.createElement('div'); grid.className = 'specialties';
  for (const specialty of groups.keys()) {
    const button = document.createElement('button'); button.textContent = label(specialty);
    button.onclick = () => show(specialty); grid.append(button);
  }
  el('categories').append(grid);
  if (!files.length) el('status').textContent = 'No Markdown references loaded. Check the Alpine source folder.';
  el('back').onclick = () => {el('categories').hidden = false; el('condition-page').hidden = true; current = [...groups.values()].flat();};
  el('count').oninput = () => {el('count-value').textContent = el('count').value;};
  el('random').disabled = !files.length;
  el('random').onclick = () => {
    if (!current.length) return;
    const topic = current[Math.floor(Math.random() * current.length)];
    for (const [specialty, topics] of groups) if (topics.includes(topic)) {show(specialty); break;}
    choose(topic);
  };
  el('start').onclick = async () => {
    if (!selected || el('start').disabled) return;
    el('start').disabled = true;
    const input = JSON.stringify({specialty: el('specialty-title').textContent, condition: selected.title, questions: Number(el('count').value)});
    try {
      const sent = await Websandbox.connection.remote.sendPrompt({text: input, sourceFiles: [selected.file]});
      el('status').textContent = sent === false ? 'Not sent. Try again.' : 'Submitted · continue in chat';
      if (sent === false) el('start').disabled = false;
    } catch (_) {el('status').textContent = 'Not sent. Try again.'; el('start').disabled = false;}
  };
}
